def _read_at(self, d,
                 interpolation='linear',
                 index=False,
                 return_basis=False):
        """
        Private function. Implements read_at() for a single depth.

        Args:
            d (float)
            interpolation (str)
            index(bool)
            return_basis (bool)

        Returns:
            float
        """
        if d in self.depths:
            if index:
                return self.depths.index(d)
            else:
                return self.depths[self.depths.index(d)]
        else:
            if interpolation == 'linear':
                if d > self.depths[-1]:
                    return self.depths[-1]
                elif d < self.depths[0]:
                    return self.depths[0]
                else:
                    return np.interp(d, self.depths, self.depths)
            elif interpolation == 'nearest':
                if d > self.depths[-1]:
                    return self.depths[-1]
                elif d < self.depths[0]:
                    return self.depths[0]
                else:
                    return np.interp(d, self.depths, self.depths,
                                     left=self.depths[0], right=self.depths[-1])
            else:
                raise ValueError('interpolation must be either linear or nearest')

